import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Load the feature card image
  const material = new MeshBasicNodeMaterial();

  // Set up texture loading
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = 'srgb';
    tex.magFilter = THREE.LinearFilter;
    tex.minFilter = THREE.LinearFilter;
    material.colorNode = texture(tex, uv());
    material.needsUpdate = true;
  });

  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene position from config
  if (config.scenePosition) {
    mesh.position.set(
      config.scenePosition[0],
      config.scenePosition[1],
      config.scenePosition[2]
    );
  }

  // Apply rotation if present
  if (config.sceneRotation) {
    mesh.rotation.set(
      config.sceneRotation[0],
      config.sceneRotation[1],
      config.sceneRotation[2]
    );
  }

  // Apply scale if present
  if (config.sceneScale) {
    mesh.scale.set(
      config.sceneScale[0],
      config.sceneScale[1],
      config.sceneScale[2]
    );
  }

  // Set up user data with cleanup handler
  mesh.userData.handlers = {};
  mesh.userData.cleanup = function() {
    geometry.dispose();
    material.dispose();
  };

  return mesh;
}
